<script setup lang="ts">
import { ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api } from '../api'
import { user, refreshUser, usePage, perform, busy } from '../state'
import { decimal, label, requestKey, positiveDecimal, stateTone } from '../domain'
import type { Row } from '../domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import DataTable from '../components/DataTable.vue'
import OperationForm from '../components/OperationForm.vue'
const cards = ref<Row[]>([]), fundAccounts = ref<Row[]>([]), entries = ref<Row[]>([]), requests = ref<Row[]>([]), tab = ref('cards'), accountFilter = ref(''), bindOpen = ref(false), moneyOpen = ref(false), changeOpen = ref(false), selected = ref<Row>({}), amount = ref(''), direction = ref('top-ups'), moneyKey = ref(requestKey())
const { loading, error, load } = usePage(async () => { [cards.value, fundAccounts.value, entries.value, requests.value] = await Promise.all([api.get('/bank-cards'), api.get('/fund-accounts'), api.get('/cash-entries' + (accountFilter.value ? '?tradingAccountId=' + accountFilter.value : '')), api.get('/card-change-requests')]); await refreshUser() })
async function cardAction(card: Row, action: string) {
  if (action === 'unbind') { try { await ElMessageBox.confirm('解绑需余额、持仓与未结业务均为零，历史记录将保留。确定申请解绑此卡？', '解绑模拟卡', { confirmButtonText: '确定解绑', cancelButtonText: '取消' }) } catch { return } }
  await perform(() => action === 'default' ? api.put('/bank-cards/' + card.id + '/default') : action === 'status' ? api.patch('/bank-cards/' + card.id + '/status', { status: card.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE' }) : api.post('/bank-cards/' + card.id + '/unbind'), load)
}
function openMoney(card: Row, operation: string) { selected.value = { ...card }; direction.value = operation; amount.value = ''; moneyKey.value = requestKey(); moneyOpen.value = true }
async function transact() { await perform(async () => { if (!positiveDecimal(amount.value)) throw new Error('请输入大于零、最多两位小数的金额'); return api.post('/trading-accounts/' + selected.value.tradingAccountId + '/' + direction.value, { amount: amount.value, requestKey: moneyKey.value }) }, async () => { moneyOpen.value = false; await load() }) }
function openChange(card: Row) { selected.value = { ...card }; changeOpen.value = true }
const bindKey = ref(requestKey()), changeKey = ref(requestKey())
async function rebind(card:Row){await perform(()=>api.post('/bank-cards',{bankName:card.bankName,holderName:card.holderName,simNumber:card.simNumber,requestKey:requestKey()}),load)}
</script>
<template><PageHeader title="银行卡与资金" subtitle="每张模拟卡关联独立交易账户，资金不跨卡借用。"><button class="button primary" :disabled="!user?.opened" @click="bindKey = requestKey(); bindOpen = true">＋ 绑定模拟卡</button><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in [['cards','银行卡与余额'],['ledger','资金流水'],['ta','基金账户'],['changes','换卡申请']]" :key="t[0]" :class="{active:tab === t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><template v-if="tab === 'cards'"><p class="notice">首次有效绑卡向首个交易账户发放 ¥100,000.00 模拟资金，后来绑卡初始余额为零。无需输入真实卡号，系统自动生成 SIM 标识。</p><div class="card-grid"><article v-for="card in cards" :key="card.id" class="bank-card"><span v-if="card.isDefault" class="default-flag">默认卡</span><h3>{{ card.bankName }}</h3><span class="status" :class="stateTone(card.status)">{{ label(card.status) }}</span> <span class="status" :class="stateTone(card.receiveState)">{{ label(card.receiveState) }}</span><div class="card-number">{{ card.simNumber }}</div><p class="muted small">{{ card.holderName }} · 交易账户 {{ card.accountNo }} · 版本 {{ card.bindingVersion }}</p><div class="card-balances"><div>可用资金（元）<b>{{ decimal(card.available) }}</b></div><div>冻结（元）<b>{{ decimal(card.frozen) }}</b></div></div><div v-if="!['UNBOUND','REPLACED'].includes(card.status)" class="toolbar"><button class="text-button" @click="openMoney(card,'top-ups')">充值</button><button class="text-button" @click="openMoney(card,'withdrawals')">提现</button><button v-if="card.status==='ACTIVE' && !card.isDefault" class="text-button" :disabled="busy > 0" @click="cardAction(card,'default')">设为默认</button><button class="text-button" :disabled="busy > 0" @click="cardAction(card,'status')">{{ card.status==='ACTIVE' ? '停用扣款' : '恢复扣款' }}</button><button class="text-button" @click="changeKey=requestKey();openChange(card)">申请换卡</button><button class="text-button danger" :disabled="busy > 0" @click="cardAction(card,'unbind')">解绑</button></div><div v-if="card.status==='UNBOUND'" class="toolbar"><button class="text-button" :disabled="busy>0" @click="rebind(card)">重新绑定此模拟卡</button><span class="muted small">复用SIM标识，新交易账户不重复发放初始资金</span></div></article></div><div v-if="!cards.length && !loading" class="empty">尚未绑定模拟卡。请先完成开户，再绑定第一张卡。</div></template><section v-else-if="tab === 'ledger'" class="panel"><div class="section-title"><h2>逐账户资金流水</h2><a class="button" href="/api/exports/cash-entries" download>导出 CSV</a></div><div class="toolbar filters"><select v-model="accountFilter" @change="load"><option value="">所有账户</option><option v-for="card in cards" :key="card.id" :value="String(card.tradingAccountId)">{{ card.bankName }} · {{ card.accountNo }}</option></select></div><DataTable :rows="entries" :columns="[{key:'createdAt',label:'时间',kind:'date'}, {key:'tradingAccountId',label:'交易账户'}, {key:'sourceType',label:'来源'}, {key:'sourceId',label:'来源编号'}, {key:'amount',label:'变动金额（元）',kind:'money'}, {key:'availableDelta',label:'可用变动（元）',kind:'money'}, {key:'frozenDelta',label:'冻结变动（元）',kind:'money'}, {key:'reason',label:'说明'}]"/></section><section v-else-if="tab==='ta'" class="panel"><h2>TA基金账户</h2><p class="muted">首次购入该登记机构产品时关联，同一TA下的多张模拟卡复用基金账户。</p><DataTable :rows="fundAccounts" :columns="[{key:'accountNo',label:'基金账户编号'}, {key:'registrarName',label:'登记机构'}, {key:'status',label:'状态',kind:'state'}]"/></section><section v-else class="panel"><h2>受控换卡记录</h2><p class="notice">换卡保留交易账户、余额与历史来源。后台核准后生效，不能靠修改默认卡把历史回款转到其他账户。</p><DataTable :rows="requests" :columns="[{key:'id',label:'申请编号'}, {key:'tradingAccountId',label:'交易账户'}, {key:'bankName',label:'银行'}, {key:'reason',label:'申请理由'}, {key:'status',label:'状态',kind:'state'}, {key:'createdAt',label:'时间',kind:'date'}, {key:'approvedAt',label:'生效时间',kind:'date'}]"/></section><el-dialog v-model="bindOpen" title="绑定模拟银行卡" width="540px"><OperationForm title="模拟身份核验" :initial="{bankName:'模拟工商银行',holderName:user?.displayName}" :fields="[{key:'bankName',label:'模拟银行名称'}, {key:'holderName',label:'模拟持卡人',hint:'必须与账户昵称一致，不填写真实身份或真实卡号'}]" :submit="value => api.post('/bank-cards',{...value,requestKey:bindKey})" button="绑定并建立交易账户" @saved="bindOpen=false;load()"/></el-dialog><el-dialog v-model="moneyOpen" :title="direction === 'top-ups' ? '模拟充值' : '模拟提现'" width="480px"><p class="notice">{{ selected.bankName }} · {{ selected.accountNo }}<br/>只操作此交易账户，可用 ¥{{ decimal(selected.available) }}。</p><form @submit.prevent="transact"><label><span>金额（元）</span><input v-model="amount" inputmode="decimal" required @input="moneyKey=requestKey()"/></label><div class="form-actions"><button class="button primary" :disabled="busy > 0">{{ busy ? '处理中…' : '确认' }}</button></div></form></el-dialog><el-dialog v-model="changeOpen" title="申请受控换卡" width="540px"><OperationForm title="同银行、同持卡人换卡" :initial="{bankName:selected.bankName,holderName:selected.holderName,reason:''}" :fields="[{key:'bankName',label:'银行'}, {key:'holderName',label:'模拟持卡人'}, {key:'reason',label:'换卡理由',type:'textarea'}]" :submit="value => api.post('/card-change-requests',{...value,tradingAccountId:selected.tradingAccountId,requestKey:changeKey})" button="提交后台核准" @saved="changeOpen=false;load()"/></el-dialog></template>
